import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class CircularHistoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String contents(CircularHistory history) {
        List<String> seen = new ArrayList<>();
        for (String s : history) {
            seen.add(s);
        }
        return seen.toString();
    }

    public static void main(String[] args) {
        CircularHistory history = new CircularHistory(3);
        check("empty history size", 0, history.size());
        check("empty history contents", "[]", contents(history));

        history.add("a");
        history.add("b");
        check("size before filling up", 2, history.size());
        check("contents before filling up", "[a, b]", contents(history));

        history.add("c");
        history.add("d");
        check("size never exceeds capacity", 3, history.size());
        check("oldest entry was dropped", "[b, c, d]", contents(history));

        history.add("e");
        history.add("f");
        check("contents after more wrapping", "[d, e, f]", contents(history));
        check("iterating twice gives the same result", "[d, e, f]", contents(history));

        Iterator<String> it = history.iterator();
        int pulled = 0;
        while (it.hasNext()) {
            it.next();
            pulled++;
        }
        check("iterator yielded every entry", 3, pulled);

        String thrown = "nothing";
        try {
            it.next();
            thrown = "no exception";
        } catch (java.util.NoSuchElementException e) {
            thrown = "NoSuchElementException";
        } catch (RuntimeException e) {
            thrown = e.getClass().getSimpleName();
        }
        check("next() past the end", "NoSuchElementException", thrown);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

