import java.util.Iterator;
import java.util.NoSuchElementException;

public class CircularHistory implements Iterable<String> {

    private final String[] items;
    private int added; // how many add() calls have happened in total

    public CircularHistory(int capacity) {
        this.items = new String[capacity];
    }

    public void add(String value) {
        items[added % items.length] = value;
        added++;
    }

    public int size() {
        return Math.min(added, items.length);
    }

    @Override
    public Iterator<String> iterator() {
        final int count = size();
        final int start = added - count;
        return new Iterator<String>() {
            private int seen = 0;

            @Override
            public boolean hasNext() {
                return seen < count;
            }

            @Override
            public String next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                String value = items[(start + seen) % items.length];
                seen++;
                return value;
            }
        };
    }
}
